import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Arrange: Mock context providers
const mockClearCart = vi.fn();
const mockProcessPayment = vi.fn();
const mockOnComplete = vi.fn();
const mockOnCancel = vi.fn();

const defaultCartItems = [
  { id: '1', name: 'Athena Figurine', price: 49.99 },
  { id: '2', name: 'Owl Pendant', price: 29.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: defaultCartItems, total: 79.98, clearCart: mockClearCart })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout - Happy Path', () => {
  it('completes full checkout flow from shipping to confirmation', async () => {
    const user = userEvent.setup();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });

    render(<Checkout onComplete={mockOnComplete} />);

    // Act: Fill shipping
    await user.type(screen.getByRole('textbox', { name: /street/i }), '123 Olympus Way');
    await user.type(screen.getByRole('textbox', { name: /city/i }), 'Athens');
    await user.selectOptions(screen.getByRole('combobox', { name: /state/i }), 'CA');
    await user.type(screen.getByRole('textbox', { name: /zip/i }), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Act: Fill payment
    await user.type(screen.getByRole('textbox', { name: /card number/i }), '4111111111111111');
    await user.type(screen.getByRole('textbox', { name: /expiry/i }), '12/25');
    await user.type(screen.getByRole('textbox', { name: /cvv/i }), '123');
    await user.type(screen.getByRole('textbox', { name: /name on card/i }), 'Athena Pallas');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Assert: Review displays correctly
    expect(screen.getByText(/athena figurine/i)).toBeInTheDocument();
    expect(screen.getByText(/\$79\.98/)).toBeInTheDocument();

    // Act: Place order
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Assert: Confirmation
    await waitFor(() => {
      expect(screen.getByRole('status')).toHaveTextContent('ORD-12345');
    });
    expect(mockOnComplete).toHaveBeenCalledWith('ORD-12345');
  });
});

describe('Checkout - Validation', () => {
  it('displays inline errors for invalid ZIP code', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    await user.type(screen.getByRole('textbox', { name: /zip/i }), 'invalid');
    await user.click(screen.getByRole('button', { name: /continue/i }));

    expect(screen.getByRole('alert')).toHaveTextContent(/valid zip/i);
    expect(screen.getByRole('textbox', { name: /zip/i })).toHaveAttribute('aria-invalid', 'true');
  });
});

describe('Checkout - Edge Cases', () => {
  it('handles empty cart gracefully', () => {
    vi.mocked(useCart).mockReturnValue({ items: [], total: 0, clearCart: mockClearCart });
    render(<Checkout onCancel={mockOnCancel} />);

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });

  it('displays payment failure and allows retry', async () => {
    mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
    // ... complete flow to review, click place order

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
    });
    expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
  });
});

describe('Checkout - Accessibility', () => {
  it('has no accessibility violations', async () => {
    const { container } = render(<Checkout />);
    expect(await axe(container)).toHaveNoViolations();
  });
});
```

